const learningStore8='gugudan-learning-v1';let storageError8='';
function saveLearning8(){try{localStorage.setItem(learningStore8,JSON.stringify({version:1,review:{learned:s8.learned,sessions:s8.sessions,problems:s8.problems,round:s8.round,excluded:s8.excluded},cards5:s5.cards,bank6:s6.bank,pending6:s6.pending,rounds6:s6.rounds,done6:s6.done,cards7:s7.cards,done5:s5.done}));storageError8=''}catch(e){storageError8='이 브라우저에 기록을 저장하지 못했어요. 현재 화면에서는 계속 풀 수 있지만, 새로고침 전에 브라우저의 저장 설정을 확인해 주세요.'}storageNote8()}
function safeCard8(c){return c&&Number.isInteger(c.n)&&Number.isInteger(c.g)&&c.n>=2&&c.n<=9&&c.g>=1&&c.g<=9}
function level8(l){return [0,1,2].includes(l)?l:null}
function safeProblem8(p){return safeCard8(p)&&Number.isInteger(p.scene)&&p.scene>=0&&p.scene<4?{scene:p.scene,n:p.n,g:p.g,item:typeof p.item==='string'?p.item.slice(0,20):scenes7[p.scene].item}:null}
function safeResult8(r){if(!r||typeof r.key!=='string')return null;const [n,g]=r.key.split(' × ').map(Number);if(!safeCard8({n,g})||level8(r.level)===null)return null;return {key:key8(n,g),level:r.level,wrong:!!r.wrong,improved:!!r.improved,type:['equation','picture','life','review'].includes(r.type)?r.type:'equation'}}
function loadLearning8(){try{const raw=localStorage.getItem(learningStore8);if(!raw)return;const data=JSON.parse(raw);if(data.version!==1)throw Error('version');const review=data.review||{};s8.learned={};for(const c of Object.values(review.learned||{})){if(!safeCard8(c))continue;const key=key8(c.n,c.g);s8.learned[key]={key,n:c.n,g:c.g,level:level8(c.level),history:Array.isArray(c.history)?c.history.filter(h=>h&&level8(h.level)!==null).map(h=>({level:h.level,wrong:!!h.wrong})):[]}}s8.sessions=(Array.isArray(review.sessions)?review.sessions:[]).filter(x=>x&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Array.isArray(x.results)).map(x=>({date:x.date,results:x.results.map(safeResult8).filter(Boolean)}));s8.problems=(Array.isArray(review.problems)?review.problems:[]).map(safeProblem8).filter(Boolean);s8.round=Number.isInteger(review.round)&&review.round>=0?review.round:0;s8.excluded=(Array.isArray(review.excluded)?review.excluded:[]).filter(k=>typeof k==='string'&&/^[2-9] × [1-9]$/.test(k));s5.cards=(Array.isArray(data.cards5)?data.cards5:[]).filter(c=>c&&typeof c.key==='string'&&/^[2-9] × [1-9]$/.test(c.key)).map(c=>{const [n,g]=c.key.split(' × ').map(Number),valid=['바로 떠올림','아는 식으로 해결','그림을 보고 해결'];return {key:key8(n,g),answer:n*g,route:valid.includes(c.route)?c.route:valid[2],history:(Array.isArray(c.history)?c.history:[]).filter(x=>valid.includes(x))}});s5.done=!!data.done5;s6.bank=(Array.isArray(data.bank6)?data.bank6:[]).filter(safeCard8).map(c=>({key:key8(c.n,c.g),n:c.n,g:c.g,answer:c.n*c.g,source:c.imported?'5단계에서 찾은 식':'앞 단계에서 만난 식',level:level8(c.level),stars:Number.isInteger(c.stars)?Math.max(0,Math.min(999,c.stars)):0,history:(Array.isArray(c.history)?c.history:[]).filter(h=>h&&level8(h.level)!==null).map(h=>({level:h.level,corrected:!!h.corrected,round:Number.isInteger(h.round)?h.round:0})),imported:!!c.imported}));s6.pending=(Array.isArray(data.pending6)?data.pending6:[]).filter(k=>s6.bank.some(c=>c.key===k));s6.rounds=Number.isInteger(data.rounds6)?data.rounds6:0;s6.done=!!data.done6;s7.cards=(Array.isArray(data.cards7)?data.cards7:[]).map(safeProblem8).filter(Boolean);s7.done=new Set(s7.cards.map(c=>c.scene)).size>=2}catch(e){storageError8='저장한 기록을 불러오지 못했어요. 현재 활동은 계속할 수 있어요. 브라우저 저장 설정을 확인해 주세요.'}}
loadLearning8();
